                ok: false,
                reason: `${basename} carries the -desktop- viewport token but its IHDR is ${dims.w}×${dims.h} — below the desktop full-viewport floor (${DESKTOP_FULL_WIDTH}px) — a crop/mobile mislabeled desktop`,
            };
        return { ok: true };
    }
    return { ok: true };
}
