// tests/harness/artifacts.ts — every read that is not a source read. R-3 and B0 (B-S12):
// source is read through ./source.ts, F-1's file set. What else a suite or a script reads is
// an artifact: a build output (`dist/`, `dist-demo/`), a run's output (a capture, a report,
// a baseline), or a file outside the repository (a temp root, an unpacked tarball, an
// installed package, a sibling checkout, a build's staging directory). An artifact read
// refuses a source file (a code file in one of the five zones, or a root config), so it
// can never hide a reference into the tree. A missing artifact fails every read; `artifactExists` is for an absence the caller
// reports. Kept free of the graph, so a script loads it without building F-1.
import { existsSync, lstatSync, readdirSync, readFileSync } from "node:fs";
import { dirname, isAbsolute, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "../..");
const CODE = /\.(ts|tsx|mts|cts|js|jsx|mjs|cjs|vue|css)$/;
const ZONE = /^(src|demo|tests|tests-visual|scripts)\//; // F-1's zones (R-5)

/** An artifact's absolute path. Relative paths are taken from the repository root. */
const artifactPath = (path: string): string => {
    const abs = resolve(ROOT, path);
    const r = relative(ROOT, abs).split("\\").join("/");
    const inside = !r.startsWith("..") && !isAbsolute(r);
    if (inside && CODE.test(r) && (ZONE.test(r) || !r.includes("/")))
        throw new Error(`harness: ${path} is source; read it through tests/harness/source.ts`);
    return abs;
};

/** An artifact's bytes. */
export function artifact(path: string): Buffer {
    return readFileSync(artifactPath(path));
}

/** An artifact's text. */
export function artifactText(path: string): string {
    return readFileSync(artifactPath(path), "utf8");
}

/** Whether an artifact exists: the predicate a caller asks before it says "build first". */
export function artifactExists(path: string): boolean {
    return existsSync(artifactPath(path));
}

/** An artifact's size, modification time and kind, read without following a link (an
 *  installed or packed file must be a real file, not a link to one). */
export function artifactStat(path: string): { size: number; mtimeMs: number; isFile: boolean; isLink: boolean } {
    const s = lstatSync(artifactPath(path));
    return { size: s.size, mtimeMs: s.mtimeMs, isFile: s.isFile(), isLink: s.isSymbolicLink() };
}

/** The files at or under an artifact directory, sorted and filtered by `suffix`, each
 *  spelled as `under` joined with its path below it (`dist` → `dist/styles/index.css`). */
export function artifactFiles({ under, suffix }: { under: string; suffix?: string | RegExp }): string[] {
    const out: string[] = [];
    const walk = (abs: string, spelled: string): void => {
        for (const entry of readdirSync(abs, { withFileTypes: true })) {
            if (entry.isDirectory()) walk(join(abs, entry.name), `${spelled}/${entry.name}`);
            else out.push(`${spelled}/${entry.name}`);
        }
    };
    walk(artifactPath(under), under.replace(/\/$/, ""));
    return out.sort().filter((f) => suffix === undefined || (typeof suffix === "string" ? f.endsWith(suffix) : suffix.test(f)));
}
